// 처음 연결 · 설치와 업로드
// 보드: Arduino Uno / 시리얼 모니터: 9600 baud
// USB를 뽑고 배선한 뒤, 아래 연결표와 코드의 핀 번호를 대조하세요.

void setup() {
  pinMode(LED_BUILTIN, OUTPUT); // 보드 위 L 표시 LED를 출력으로 사용합니다.
  Serial.begin(9600); // 도구 → 시리얼 모니터도 같은 속도로 맞춥니다.
}
void loop() {
  digitalWrite(LED_BUILTIN, HIGH); // 보드 안 LED를 켭니다. 외부 배선은 없습니다.
  Serial.println("UNO ready");
  delay(500); // 밀리초: 1000이 1초입니다.
  digitalWrite(LED_BUILTIN, LOW);
  delay(500);
}

// 빵판 읽기 · 저항과 LED
// 보드: Arduino Uno / 시리얼 모니터: 9600 baud
// USB를 뽑고 배선한 뒤, 아래 연결표와 코드의 핀 번호를 대조하세요.

const int LED_PIN = 8; // UNO에서 8이라고 적힌 소켓입니다.
void setup() {
  pinMode(LED_PIN, OUTPUT); // 전압을 내보내는 역할로 정합니다.
}
void loop() {
  digitalWrite(LED_PIN, HIGH); // 8번에 HIGH를 내보내 LED를 켭니다.
  delay(1000); // 켜진 상태를 1초 유지합니다.
  digitalWrite(LED_PIN, LOW); // 8번을 LOW로 바꿔 LED를 끕니다.
  delay(1000);
}

// 택트 스위치 · 누르면 값 바꾸기
// 보드: Arduino Uno / 시리얼 모니터: 9600 baud
// USB를 뽑고 배선한 뒤, 아래 연결표와 코드의 핀 번호를 대조하세요.

const int SENSOR_PIN = 2; // 연결표의 신호 핀과 같습니다.
void setup() {
  pinMode(SENSOR_PIN, INPUT_PULLUP); // 내부 저항으로 미연결 때 HIGH를 유지합니다.
  Serial.begin(9600);
}
void loop() {
  bool closed = digitalRead(SENSOR_PIN) == LOW; // GND와 붙으면 LOW입니다.
  Serial.println(closed ? "closed" : "open"); // 조건에 따라 표시할 글자를 고릅니다.
  delay(50);
}

// 세 가지 LED · 신호등 만들기
// 보드: Arduino Uno / 시리얼 모니터: 9600 baud
// USB를 뽑고 배선한 뒤, 아래 연결표와 코드의 핀 번호를 대조하세요.

const int RED = 8, YELLOW = 9, GREEN = 10;
// 같은 모양의 일을 함수로 묶어 어느 LED를 켤지 전달합니다.
void showLight(int activePin) {
  digitalWrite(RED, activePin == RED);
  digitalWrite(YELLOW, activePin == YELLOW);
  digitalWrite(GREEN, activePin == GREEN);
}
void setup() {
  pinMode(RED, OUTPUT); pinMode(YELLOW, OUTPUT); pinMode(GREEN, OUTPUT);
}
void loop() {
  showLight(RED); delay(2000);
  showLight(GREEN); delay(2000);
  showLight(YELLOW); delay(700);
}

