// DHT11 · 온도와 습도
// 보드: Arduino Uno / 시리얼 모니터: 9600 baud
// USB를 뽑고 배선한 뒤, 아래 연결표와 코드의 핀 번호를 대조하세요.

#include <DHT.h> // 라이브러리 관리자에서 DHT sensor library by Adafruit 설치
DHT dht(2, DHT11); // 첫 값은 DATA 핀, 두 번째는 센서 종류입니다.
void setup() { Serial.begin(9600); dht.begin(); }
void loop() {
  delay(2000); // DHT11을 너무 자주 읽지 않습니다.
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();
  if (isnan(temperature) || isnan(humidity)) { // NaN은 읽기에 실패한 값입니다.
    Serial.println("DHT read failed");
    return; // 이번 loop 실행만 끝내고 다음 읽기를 기다립니다.
  }
  Serial.print("temperature_c="); Serial.print(temperature);
  Serial.print(", humidity_pct="); Serial.println(humidity);
}

// LM35DZ · 전압을 섭씨로
// 보드: Arduino Uno / 시리얼 모니터: 9600 baud
// USB를 뽑고 배선한 뒤, 아래 연결표와 코드의 핀 번호를 대조하세요.

void setup() { Serial.begin(9600); }
void loop() {
  int raw = analogRead(A0); // 0~1023의 ADC 값
  float volts = raw * (5.0 / 1023.0); // 기준전압을 5.0V로 두는 근삿값
  float celsius = volts * 100.0; // 10mV/°C = 0.01V/°C
  Serial.print("raw="); Serial.print(raw);
  Serial.print(", temperature_c="); Serial.println(celsius, 1);
  delay(500);
}

// RGB LED · 세 가지 빛 섞기
// 보드: Arduino Uno / 시리얼 모니터: 9600 baud
// USB를 뽑고 배선한 뒤, 아래 연결표와 코드의 핀 번호를 대조하세요.

const int R = 9, G = 10, B = 11; // ~ 표시 PWM 핀입니다.
const bool COMMON_ANODE = false; // 공통 -면 false. 공통 +형은 배선도 함께 바꿔야 합니다.
void color(byte red, byte green, byte blue) {
  analogWrite(R, COMMON_ANODE ? 255-red : red);
  analogWrite(G, COMMON_ANODE ? 255-green : green);
  analogWrite(B, COMMON_ANODE ? 255-blue : blue);
}
void setup() { pinMode(R, OUTPUT); pinMode(G, OUTPUT); pinMode(B, OUTPUT); }
void loop() {
  color(255,0,0); delay(800); // 빨강
  color(0,255,0); delay(800); // 초록
  color(0,0,255); delay(800); // 파랑
  color(120,40,160); delay(800); // 섞은 색
}

